function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100000) return 'Each vector has 1 to 10^5 entries.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each entry is an integer from 0 to 100.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [nums1, nums2] = input;
  // Build both vectors with the learner's class, as LeetCode's driver does, then multiply them.
  const v1 = new solve(nums1.slice());
  const v2 = new solve(nums2.slice());
  if (typeof v1.dotProduct !== 'function') throw new Error('SparseVector needs a dotProduct(vec) method.');
  const result = v1.dotProduct(v2);
  if (typeof result !== 'number') throw new Error('dotProduct(vec) must return a number.');
  return result;
}

