class SparseVector {
  constructor(nums) {
    this.entries = new Map();
    for (let i = 0; i < nums.length; i++) {
      if (nums[i] !== 0) {
        this.entries.set(i, nums[i]);
      }
    }
  }

  dotProduct(vec) {
    let small = this.entries;
    let large = vec.entries;
    if (small.size > large.size) {
      [small, large] = [large, small];
    }
    let total = 0;
    for (const [index, value] of small) {
      if (large.has(index)) {
        total += value * large.get(index);
      }
    }
    return total;
  }
}

