  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const vector = () => {
    const density = rand() < 0.2 ? 1 : rand() * 0.5;
    const top = rand() < 0.5 ? 100 : 5;
    return Array.from({ length: n }, () => (rand() < density ? Math.floor(rand() * (top + 1)) : 0));
  };
  return [vector(), vector()];
}
